function D([string]$b){[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b))}; $Dir=D '__DIR64__'; $Name=D '__NAME64__'; $shell = New-Object -ComObject Shell.Application; if (-not $shell.NameSpace($Dir)) { exit 2 }; Start-Process explorer.exe -ArgumentList $Dir; $w = $null; foreach ($n in 1..40) { Start-Sleep -Milliseconds 250; $fresh = New-Object -ComObject Shell.Application; foreach ($cand in @($fresh.Windows())) { if ($cand.Document.Folder.Self.Path -eq $Dir) { $w = $cand; break } }; if ($w) { break } }; if (-not $w) { exit 3 }; $folder = $shell.NameSpace($Dir); $target = $null; foreach ($i in $folder.Items()) { if ($i.Name -eq $Name) { $target = $i } }; if (-not $target) { exit 4 }; $w.Visible = $true; $w.Document.SelectItem($target, 29); $w.Document.FocusedItem | Out-Null; if ($w.Document.FocusedItem.Name -ne $Name) { exit 5 }
